-- PowerPay v1.0.0 baseline PostgreSQL schema.
-- IDs using Prisma @default(cuid()) are generated by the application unless explicitly supplied.

CREATE TYPE "Chain" AS ENUM ('SOLANA','SUI');
CREATE TYPE "PaymentStatus" AS ENUM ('CREATED','LOCKED','SIGNING','SIGNED','SUBMITTED','CONFIRMING','CONFIRMED','SETTLING','SETTLED','RECOVERY_REQUIRED','FAILED','EXPIRED','CANCELLED');
CREATE TYPE "PaymentAttemptStatus" AS ENUM ('CREATED','SIGNING','SIGNED','SUBMITTING','SUBMITTED','CONFIRMING','CONFIRMED','FAILED','EXPIRED','CANCELLED');
CREATE TYPE "MerchantTrustStatus" AS ENUM ('UNVERIFIED','PENDING','VERIFIED','RESTRICTED','SUSPENDED');
CREATE TYPE "WalletConnectionStatus" AS ENUM ('CONNECTED','DISCONNECTED','REVOKED','UNSUPPORTED');
CREATE TYPE "WalletPermission" AS ENUM ('READ_ADDRESS','READ_BALANCES','REQUEST_SIGNATURE','REQUEST_TRANSACTION');

CREATE TABLE "User" (
  "id" TEXT PRIMARY KEY,
  "externalId" TEXT NOT NULL UNIQUE,
  "email" TEXT,
  "displayName" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "Profile" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,
  "defaultAsset" TEXT NOT NULL DEFAULT 'USDC',
  "secondaryAsset" TEXT NOT NULL DEFAULT 'EURC',
  "displayCurrency" TEXT NOT NULL DEFAULT 'EUR',
  "locale" TEXT NOT NULL DEFAULT 'en-FI',
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "Device" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "fingerprint" TEXT NOT NULL UNIQUE,
  "platform" TEXT NOT NULL,
  "trusted" BOOLEAN NOT NULL DEFAULT false,
  "lastSeenAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "Wallet" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "chain" "Chain" NOT NULL,
  "address" TEXT NOT NULL,
  "label" TEXT,
  "walletType" TEXT,
  "status" "WalletConnectionStatus" NOT NULL DEFAULT 'CONNECTED',
  "primary" BOOLEAN NOT NULL DEFAULT false,
  "connectedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "lastUsedAt" TIMESTAMPTZ,
  "revokedAt" TIMESTAMPTZ,
  CONSTRAINT "Wallet_chain_address_key" UNIQUE ("chain","address")
);
CREATE INDEX "Wallet_userId_chain_status_idx" ON "Wallet"("userId","chain","status");

CREATE TABLE "WalletConsent" (
  "id" TEXT PRIMARY KEY,
  "walletId" TEXT NOT NULL REFERENCES "Wallet"("id") ON DELETE CASCADE,
  "permissions" "WalletPermission"[] NOT NULL,
  "acceptedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "revokedAt" TIMESTAMPTZ
);
CREATE INDEX "WalletConsent_walletId_revokedAt_idx" ON "WalletConsent"("walletId","revokedAt");

CREATE TABLE "Merchant" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "trustStatus" "MerchantTrustStatus" NOT NULL DEFAULT 'UNVERIFIED',
  "settlementWallet" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "MerchantLocation" (
  "id" TEXT PRIMARY KEY,
  "merchantId" TEXT NOT NULL REFERENCES "Merchant"("id") ON DELETE CASCADE,
  "name" TEXT NOT NULL,
  "city" TEXT,
  "country" TEXT,
  "terminalId" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "MerchantLocation_merchantId_idx" ON "MerchantLocation"("merchantId");

CREATE TABLE "Checkout" (
  "id" TEXT PRIMARY KEY,
  "merchantId" TEXT NOT NULL REFERENCES "Merchant"("id") ON DELETE CASCADE,
  "network" "Chain" NOT NULL DEFAULT 'SOLANA',
  "asset" TEXT NOT NULL DEFAULT 'USDC',
  "amount" NUMERIC(40,18) NOT NULL,
  "recipient" TEXT NOT NULL,
  "reference" TEXT NOT NULL UNIQUE,
  "nonce" TEXT NOT NULL UNIQUE,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "multiUse" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "Checkout_merchantId_expiresAt_idx" ON "Checkout"("merchantId","expiresAt");

CREATE TABLE "QrNonce" (
  "nonce" TEXT PRIMARY KEY,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "consumedAt" TIMESTAMPTZ,
  "paymentIntentId" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "QrNonce_expiresAt_consumedAt_idx" ON "QrNonce"("expiresAt","consumedAt");

CREATE TABLE "PaymentIntent" (
  "id" TEXT PRIMARY KEY,
  "idempotencyKey" TEXT NOT NULL UNIQUE,
  "userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL,
  "merchantId" TEXT REFERENCES "Merchant"("id") ON DELETE SET NULL,
  "source" TEXT NOT NULL,
  "network" TEXT NOT NULL,
  "asset" TEXT NOT NULL,
  "amount" NUMERIC(40,18) NOT NULL,
  "fiatCurrency" TEXT NOT NULL,
  "recipient" TEXT NOT NULL,
  "reference" TEXT,
  "checkoutId" TEXT,
  "nonce" TEXT,
  "expiresAt" TIMESTAMPTZ,
  "status" "PaymentStatus" NOT NULL DEFAULT 'CREATED',
  "lockedAt" TIMESTAMPTZ,
  "lockHash" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "PaymentIntent_userId_createdAt_idx" ON "PaymentIntent"("userId","createdAt");
CREATE INDEX "PaymentIntent_merchantId_createdAt_idx" ON "PaymentIntent"("merchantId","createdAt");
CREATE INDEX "PaymentIntent_status_createdAt_idx" ON "PaymentIntent"("status","createdAt");
CREATE INDEX "PaymentIntent_checkoutId_idx" ON "PaymentIntent"("checkoutId");

CREATE TABLE "PaymentQuote" (
  "id" TEXT PRIMARY KEY,
  "paymentIntentId" TEXT NOT NULL REFERENCES "PaymentIntent"("id") ON DELETE CASCADE,
  "asset" TEXT NOT NULL,
  "network" TEXT NOT NULL,
  "subtotal" NUMERIC(40,18) NOT NULL,
  "serviceFee" NUMERIC(40,18) NOT NULL,
  "protocolFee" NUMERIC(40,18) NOT NULL,
  "networkFee" NUMERIC(40,18) NOT NULL,
  "total" NUMERIC(40,18) NOT NULL,
  "quoteHash" TEXT UNIQUE,
  "signature" TEXT,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "PaymentQuote_paymentIntentId_expiresAt_idx" ON "PaymentQuote"("paymentIntentId","expiresAt");

CREATE TABLE "PaymentAttempt" (
  "id" TEXT PRIMARY KEY,
  "idempotencyKey" TEXT NOT NULL UNIQUE,
  "paymentIntentId" TEXT NOT NULL REFERENCES "PaymentIntent"("id") ON DELETE CASCADE,
  "sequence" INTEGER NOT NULL,
  "network" TEXT NOT NULL,
  "walletAddress" TEXT,
  "feeQuoteId" TEXT,
  "status" "PaymentAttemptStatus" NOT NULL DEFAULT 'CREATED',
  "transactionId" TEXT,
  "signedTransactionHash" TEXT,
  "errorCode" TEXT,
  "errorMessage" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "PaymentAttempt_paymentIntentId_sequence_key" UNIQUE ("paymentIntentId","sequence")
);
CREATE INDEX "PaymentAttempt_transactionId_idx" ON "PaymentAttempt"("transactionId");
CREATE INDEX "PaymentAttempt_status_updatedAt_idx" ON "PaymentAttempt"("status","updatedAt");

CREATE TABLE "LedgerEntry" (
  "id" TEXT PRIMARY KEY,
  "paymentIntentId" TEXT NOT NULL REFERENCES "PaymentIntent"("id") ON DELETE RESTRICT,
  "attemptId" TEXT REFERENCES "PaymentAttempt"("id") ON DELETE RESTRICT,
  "type" TEXT NOT NULL,
  "status" "PaymentStatus" NOT NULL,
  "transactionId" TEXT,
  "metadata" JSONB,
  "createdAt" TIMESTAMPTZ NOT NULL
);
CREATE INDEX "LedgerEntry_paymentIntentId_createdAt_idx" ON "LedgerEntry"("paymentIntentId","createdAt");
CREATE INDEX "LedgerEntry_transactionId_idx" ON "LedgerEntry"("transactionId");

CREATE TABLE "PaymentReceipt" (
  "receiptId" TEXT PRIMARY KEY,
  "paymentIntentId" TEXT NOT NULL UNIQUE REFERENCES "PaymentIntent"("id") ON DELETE RESTRICT,
  "attemptId" TEXT NOT NULL,
  "network" TEXT NOT NULL,
  "transactionId" TEXT NOT NULL,
  "merchantId" TEXT,
  "merchantName" TEXT,
  "payer" TEXT,
  "asset" TEXT NOT NULL,
  "amount" NUMERIC(40,18) NOT NULL,
  "fees" JSONB NOT NULL,
  "timestamp" TIMESTAMPTZ NOT NULL,
  "settlementStatus" TEXT NOT NULL
);
CREATE INDEX "PaymentReceipt_transactionId_idx" ON "PaymentReceipt"("transactionId");
CREATE INDEX "PaymentReceipt_timestamp_idx" ON "PaymentReceipt"("timestamp");

CREATE TABLE "Refund" (
  "id" TEXT PRIMARY KEY,
  "paymentIntentId" TEXT NOT NULL,
  "amount" NUMERIC(40,18) NOT NULL,
  "asset" TEXT NOT NULL,
  "reason" TEXT,
  "transactionId" TEXT,
  "status" TEXT NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "Refund_paymentIntentId_createdAt_idx" ON "Refund"("paymentIntentId","createdAt");

CREATE TABLE "Settlement" (
  "id" TEXT PRIMARY KEY,
  "paymentIntentId" TEXT NOT NULL UNIQUE,
  "attemptId" TEXT NOT NULL,
  "transactionId" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "settledAt" TIMESTAMPTZ NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "Token" (
  "id" TEXT PRIMARY KEY,
  "chain" "Chain" NOT NULL,
  "network" TEXT NOT NULL,
  "mint" TEXT NOT NULL,
  "symbol" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "decimals" INTEGER NOT NULL,
  "tokenProgram" TEXT,
  "metadataUri" TEXT,
  "imageUrl" TEXT,
  "verified" BOOLEAN NOT NULL DEFAULT false,
  "enabledForPayments" BOOLEAN NOT NULL DEFAULT false,
  "enabledForSwap" BOOLEAN NOT NULL DEFAULT false,
  "enabledForBridge" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT "Token_chain_network_mint_key" UNIQUE ("chain","network","mint")
);
CREATE INDEX "Token_symbol_enabledForPayments_idx" ON "Token"("symbol","enabledForPayments");

CREATE TABLE "RpcProvider" (
  "id" TEXT PRIMARY KEY,
  "chain" "Chain" NOT NULL,
  "network" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "rpcUrlEncrypted" TEXT NOT NULL,
  "websocketUrlEncrypted" TEXT,
  "enabled" BOOLEAN NOT NULL DEFAULT true,
  "priority" INTEGER NOT NULL DEFAULT 100,
  "latencyMs" INTEGER,
  "status" TEXT NOT NULL DEFAULT 'UNKNOWN',
  "lastHealthCheck" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "RpcProvider_chain_network_enabled_priority_idx" ON "RpcProvider"("chain","network","enabled","priority");

CREATE TABLE "ProgramDeployment" (
  "id" TEXT PRIMARY KEY,
  "chain" "Chain" NOT NULL,
  "network" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "programId" TEXT NOT NULL,
  "version" TEXT NOT NULL,
  "idlHash" TEXT,
  "deploymentHash" TEXT,
  "deploymentSlot" BIGINT,
  "authority" TEXT,
  "verified" BOOLEAN NOT NULL DEFAULT false,
  "status" TEXT NOT NULL DEFAULT 'PENDING',
  "activeFrom" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "retiredAt" TIMESTAMPTZ,
  CONSTRAINT "ProgramDeployment_chain_network_name_version_key" UNIQUE ("chain","network","name","version")
);
CREATE INDEX "ProgramDeployment_chain_network_name_retiredAt_idx" ON "ProgramDeployment"("chain","network","name","retiredAt");

CREATE TABLE "FeatureFlag" (
  "id" TEXT PRIMARY KEY,
  "key" TEXT NOT NULL UNIQUE,
  "enabled" BOOLEAN NOT NULL DEFAULT false,
  "metadata" JSONB,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "SwapQuote" (
  "id" TEXT PRIMARY KEY,
  "provider" TEXT NOT NULL,
  "chain" "Chain" NOT NULL,
  "inputAsset" TEXT NOT NULL,
  "outputAsset" TEXT NOT NULL,
  "inputAmountAtomic" NUMERIC(40,0) NOT NULL,
  "expectedOutputAtomic" NUMERIC(40,0) NOT NULL,
  "minimumOutputAtomic" NUMERIC(40,0) NOT NULL,
  "priceImpactBps" INTEGER NOT NULL,
  "estimatedNetworkFeeUsd" NUMERIC(24,8),
  "routeJson" JSONB NOT NULL,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE "CrossChainTransfer" (
  "id" TEXT PRIMARY KEY,
  "provider" TEXT NOT NULL,
  "sourceChain" "Chain" NOT NULL,
  "destinationChain" "Chain" NOT NULL,
  "asset" TEXT NOT NULL,
  "amountAtomic" NUMERIC(40,0) NOT NULL,
  "recipient" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "sourceTransaction" TEXT,
  "attestationId" TEXT,
  "destinationTransaction" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "CrossChainTransfer_status_updatedAt_idx" ON "CrossChainTransfer"("status","updatedAt");

CREATE TABLE "Notification" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "severity" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "readAt" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");

CREATE TABLE "IdempotencyRecord" (
  "key" TEXT PRIMARY KEY,
  "scope" TEXT NOT NULL,
  "resourceType" TEXT NOT NULL,
  "resourceId" TEXT NOT NULL,
  "responseHash" TEXT,
  "expiresAt" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "IdempotencyRecord_resourceType_resourceId_idx" ON "IdempotencyRecord"("resourceType","resourceId");

CREATE TABLE "SecurityEvent" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT,
  "deviceId" TEXT,
  "severity" TEXT NOT NULL,
  "eventType" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "metadata" JSONB,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "SecurityEvent_userId_createdAt_idx" ON "SecurityEvent"("userId","createdAt");

CREATE TABLE "AuditLog" (
  "id" TEXT PRIMARY KEY,
  "actorId" TEXT,
  "action" TEXT NOT NULL,
  "objectType" TEXT NOT NULL,
  "objectId" TEXT NOT NULL,
  "requestId" TEXT,
  "metadata" JSONB,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "AuditLog_objectType_objectId_createdAt_idx" ON "AuditLog"("objectType","objectId","createdAt");
